CREATE OR REPLACE FUNCTION public.origem_check_attempt(p_ip_hash text, p_success boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_ip_hash)); SELECT count(*) INTO n FROM public.origem_attempts WHERE ip_hash=p_ip_hash AND NOT succeeded AND created_at > now()-interval '15 minutes'; IF n >= 8 THEN RETURN false; END IF; IF p_success IS NOT NULL THEN INSERT INTO public.origem_attempts(ip_hash,succeeded) VALUES(p_ip_hash,p_success); END IF; RETURN true; END $$;